import json, subprocess
from s2 import *
BCSS = '<style>\n.hl{position:absolute;left:60px;width:1800px;height:2px;background:#E1E7E8}\n.foot{position:absolute;left:60px;top:1020px;width:1800px;font:15px Inter,sans-serif;color:#33444b;display:flex;gap:36px}\n.foot b{color:#1F4E5F}\n.col{position:absolute;display:flex;flex-direction:column;gap:9px;font-family:Inter,sans-serif}\n.ann{position:relative;background:#fff;border:1px solid #D9E2E4;border-radius:12px;padding:10px 14px 11px 14px;box-shadow:0 6px 16px -10px rgba(31,78,95,.35)}\n.ann .t{font-size:16px;font-weight:700;color:#1E2B2F;padding-left:30px;line-height:1.35;letter-spacing:-.1px;display:flex;align-items:center;gap:8px}\n.ann .r{font-size:13.5px;color:#33444b;line-height:1.42;margin-top:3px}\n.ann .r em{font-style:normal;font-weight:700;color:#1F4E5F;font-size:12px;letter-spacing:.6px;text-transform:uppercase;margin-right:5px}\n.ann .tag{margin-left:auto;white-space:nowrap;font-size:12px;font-weight:600;color:#1F4E5F;background:#E8F1EF;border-radius:10px;padding:2px 9px}\n.ann .n{position:absolute;left:13px;top:10px;width:22px;height:22px;border-radius:11px;background:#1F4E5F;color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center}\n.badge{position:absolute;width:24px;height:24px;border-radius:12px;background:#1F4E5F;border:2px solid #fff;color:#fff;font:700 12px Inter,sans-serif;display:flex;align-items:center;justify-content:center;z-index:20;box-shadow:0 2px 6px rgba(0,0,0,.25)}\nsvg.ov{position:absolute;left:0;top:0;z-index:15;pointer-events:none}\n.dim{position:absolute;font:700 13px Inter,sans-serif;color:#1F4E5F;background:#fff;padding:0 4px;z-index:18;white-space:nowrap}\n.panel{position:absolute;font-family:Inter,sans-serif;color:#1E2B2F}\n.panel h4{font-size:19px;font-weight:700;color:#1F4E5F;margin-bottom:10px}\n.ann .tag.part{background:#F6EEDC;color:#7A5B1E}.ann .tag.no{background:#F3E4DF;color:#8A3F2B}\n.small{font-size:14px;color:#56666c}\n.sw4{display:flex;gap:18px;position:absolute;font:13px Inter,sans-serif;color:#1E2B2F}\n</style>'
JS = '<script>\nfunction tgt(k){return k.includes(\'.\')?document.querySelector(\'[data-a="\'+k.split(\'.\')[0]+\'"] [data-a="\'+k.split(\'.\').slice(1).join(\'.\')+\'"]\'):document.querySelector(\'[data-a="\'+k+\'"]\');}\nfunction layout(){\n document.querySelectorAll(\'.col[data-auto]\').forEach(c=>{\n  const top0=c.getBoundingClientRect().top, lim=+(c.dataset.bottom||990);\n  const anns=[...c.querySelectorAll(\'.ann\')];\n  anns.forEach(a=>{const t=a.dataset.t?tgt(a.dataset.t):null;const r=t?t.getBoundingClientRect():null;\n    a._ty=r?r.top+r.height/2+(+(a.dataset.dy||0)):0;a._h=a.getBoundingClientRect().height;});\n  anns.sort((x,y)=>x._ty-y._ty);\n  c.style.display=\'block\';c.style.height=\'0px\';\n  let prev=top0-8; const pos=[];\n  anns.forEach(a=>{let t=Math.max(a._ty-30,prev+8);pos.push(t);prev=t+a._h;});\n  let over=prev-lim; if(over>0){for(let i=anns.length-1;i>=0&&over>0;i--){pos[i]-=over; if(i>0){const gap=pos[i]-(pos[i-1]+anns[i-1]._h)-8; over=gap<0?-gap:0;}}}\n  anns.forEach((a,i)=>{a.style.position=\'absolute\';a.style.left=\'0\';a.style.width=\'100%\';a.style.top=(pos[i]-top0)+\'px\';});\n });\n}\nfunction draw(){\n layout();\n const svg=document.querySelector(\'svg.ov\');\n document.querySelectorAll(\'.ann[data-t]\').forEach(a=>{\n  const t=tgt(a.dataset.t); if(!t) return;\n  const r=t.getBoundingClientRect(), b=a.getBoundingClientRect();\n  const side=a.dataset.side; const pt=a.dataset.pt||\'edge\';\n  let x,y=r.top+r.height/2+(+(a.dataset.dy||0));\n  if(side===\'B\'){const bb=a.getBoundingClientRect();const l=document.createElementNS(\'http://www.w3.org/2000/svg\',\'line\');const dv=t.closest(\'.dev\').getBoundingClientRect();const tx=dv.left+dv.width/2,ty=dv.bottom-12;l.setAttribute(\'x1\',bb.left+bb.width/2);l.setAttribute(\'y1\',bb.top);l.setAttribute(\'x2\',tx);l.setAttribute(\'y2\',dv.bottom+3);l.setAttribute(\'stroke\',\'#1F4E5F\');l.setAttribute(\'stroke-width\',\'1.6\');svg.appendChild(l);const g=document.createElement(\'div\');g.className=\'badge\';g.textContent=a.querySelector(\'.n\').textContent;g.style.left=(tx-12)+\'px\';g.style.top=(dv.bottom-9)+\'px\';document.body.appendChild(g);const g2=g.cloneNode(true);g2.style.left=(r.right-14)+\'px\';g2.style.top=(r.top-10)+\'px\';document.body.appendChild(g2);return;}\n  if(pt===\'edge\'){const ph=t.closest(\'.dev\');const pr=ph?ph.getBoundingClientRect():r;x=side===\'L\'?pr.left-2:pr.right+2;}\n  else x= pt===\'l\'? r.left : pt===\'r\'? r.right : r.left+r.width/2;\n  x+= +(a.dataset.dx||0);\n  const sx= side===\'L\'? b.right : b.left, sy=b.top+Math.min(30,b.height/2);\n  const l=document.createElementNS(\'http://www.w3.org/2000/svg\',\'line\');\n  l.setAttribute(\'x1\',sx);l.setAttribute(\'y1\',sy);l.setAttribute(\'x2\',x);l.setAttribute(\'y2\',y);\n  l.setAttribute(\'stroke\',\'#1F4E5F\');l.setAttribute(\'stroke-width\',\'1.6\');svg.appendChild(l);\n  if(pt===\'edge\'){const l2=document.createElementNS(\'http://www.w3.org/2000/svg\',\'line\');const ex=side===\'L\'?r.left:r.right;\n   l2.setAttribute(\'x1\',x);l2.setAttribute(\'y1\',y);l2.setAttribute(\'x2\',ex);l2.setAttribute(\'y2\',y);\n   l2.setAttribute(\'stroke\',\'#1F4E5F\');l2.setAttribute(\'stroke-width\',\'1.5\');l2.setAttribute(\'stroke-dasharray\',\'3 3\');svg.appendChild(l2);}\n  const g=document.createElement(\'div\');g.className=\'badge\';g.textContent=a.querySelector(\'.n\').textContent;\n  g.style.left=(x-12)+\'px\';g.style.top=(y-12)+\'px\';document.body.appendChild(g);\n });\n}\nwindow.addEventListener(\'load\',()=>setTimeout(draw,50));\n</script>'
def _tag(spec):
    name, v = (spec.split("|") + ["ok"])[:2]
    word = {"ok": "meets", "part": "partly", "no": "fails"}[v]
    return f'<span class="tag {v}">{name}: {word}</span>'
def ann(n, title, does, why, spec, target=None, side="L", pt=None, dy=0, build=None):
    a = f' data-t="{target}" data-side="{side}"' if target else ""
    if pt: a += f' data-pt="{pt}"'
    if dy: a += f' data-dy="{dy}"'
    bl = f'<div class="r"><em>Build</em>{build}</div>' if build else ""
    return (f'<div class="ann"{a}><span class="n">{n}</span><div class="t">{title}</div>'
            f'<div class="r"><em>Does</em>{does}</div><div class="r"><em>Why</em>{why}</div>{bl}</div>').replace('<div class="t">'+title+'</div>', '<div class="t">'+title+_tag(spec)+'</div>')
def box(x, y, w, item):
    return f'<div class="col" style="left:{x}px;top:{y}px;width:{w}px">{item}</div>'
def col(x, y, w, items, bottom=995):
    return f'<div class="col" data-auto="1" data-bottom="{bottom}" style="left:{x}px;top:{y}px;width:{w}px">{"".join(items)}</div>'
def frame(inner, foot=()):
    f = "".join(f"<span>{x}</span>" for x in foot)
    return (f'<div class="hl" style="top:150px"></div><div class="hl" style="top:1000px"></div><div class="foot">{f}</div>'
            f'<svg class="ov" width="1920" height="1080"></svg>{inner}')
def page(body, extra=""):
    return f"<!doctype html><html><head><meta charset='utf-8'>{BASE}{extra}{BCSS}{JS}</head><body>{body}</body></html>"
def dev(inner, left, top, scale, pid):
    return f'<div class="dev" data-a="{pid}" style="left:{left}px;top:{top}px;transform:scale({scale})">{inner}</div>'
def cap(text, left, top, width, sub=""):
    return f'<div class="cap" style="left:{left}px;top:{top}px;width:{width}px">{text}' + (f"<small>{sub}</small>" if sub else "") + '</div>'
def render(name, html):
    open(f'/root/r/b/{name}.html','w').write(html)
    subprocess.run(['node','render.js',f'/root/r/b/{name}.html'],check=True,capture_output=True)
    return json.load(open(f'/root/r/b/{name}.json'))
def dim_h(x1, x2, y, label):
    return (f'<svg style="position:absolute;left:0;top:0;z-index:16" width="1920" height="1080"><g stroke="#1F4E5F" stroke-width="1.3">'
            f'<line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}"/><line x1="{x1}" y1="{y-6}" x2="{x1}" y2="{y+6}"/><line x1="{x2}" y1="{y-6}" x2="{x2}" y2="{y+6}"/></g></svg>'
            f'<div class="dim" style="left:{(x1+x2)/2-40}px;top:{y-9}px;width:80px;text-align:center">{label}</div>')
def dim_v(x, y1, y2, label, left=True):
    lx = x - 66 if left else x + 7
    return (f'<svg style="position:absolute;left:0;top:0;z-index:16" width="1920" height="1080"><g stroke="#1F4E5F" stroke-width="1.3">'
            f'<line x1="{x}" y1="{y1}" x2="{x}" y2="{y2}"/><line x1="{x-5}" y1="{y1}" x2="{x+5}" y2="{y1}"/><line x1="{x-5}" y1="{y2}" x2="{x+5}" y2="{y2}"/></g></svg>'
            f'<div class="dim" style="left:{lx}px;top:{(y1+y2)/2-9}px">{label}</div>')
